#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int countLargestGroup(int n) {
        unordered_map<int, int> count;
        int maxSize = 0;
        for (int i = 1; i <= n; ++i) {
            int sum = 0, x = i;
            while (x) {
                sum += x % 10;
                x /= 10;
            }
            maxSize = max(maxSize, ++count[sum]);
        }
        int res = 0;
        for (auto& [k, v] : count)
            if (v == maxSize) res++;
        return res;
    }
};
